const nw = msg.data.new_state;
const ow = msg.data.old_state;

if (!nw || !nw.attributes || !Array.isArray(nw.attributes.lista_przedmiotow)) return null;

const nowePrzedmioty = nw.attributes.lista_przedmiotow;
// Pamięć podręczna ocen osobno dla każdej encji
const cacheKey = 'oceny_cache_' + nw.entity_id.replace(/\./g, '_');
const starePrzedmioty = context.get(cacheKey) || (ow && ow.attributes ? ow.attributes.lista_przedmiotow : undefined);
context.set(cacheKey, nowePrzedmioty);

// Brak punktu odniesienia (np. wysłanie stanu przy starcie przepływu): tylko zapamiętujemy.
if (!Array.isArray(starePrzedmioty)) return null;

// Ocena = przedmiot + wpis + data + opis; liczymy wystąpienia, żeby druga identyczna ocena też była nowa.
const klucz = (p, o) => `${p.przedmiot}|${o.w}|${o.d}|${o.i}`;
const stare = {};
starePrzedmioty.forEach(p => (p.oceny || []).forEach(o => {
    const k = klucz(p, o);
    stare[k] = (stare[k] || 0) + 1;
}));

const fn = nw.attributes.friendly_name || "";
const imie = fn.split(' (')[0].replace('Oceny: ', '') || "Uczeń";
let wiadomosci = [];

nowePrzedmioty.forEach(p => (p.oceny || []).forEach(o => {
    const k = klucz(p, o);
    if (stare[k] > 0) {
        stare[k]--;
        return;
    }
    // Format "**ocena**" czyta węzeł "function 13" (wyciąga ocenę spomiędzy gwiazdek).
    wiadomosci.push({
        payload: {
            title: `Nowa ocena: ${p.przedmiot}`,
            message: `${imie} otrzymał(a) **${o.w}** z przedmiotu **${p.przedmiot}**`,
            notification_id: "vultron_ocena_" + Date.now() + "_" + wiadomosci.length
        }
    });
}));

if (wiadomosci.length > 0) return [wiadomosci];
return null;

// Pobieramy wiadomość tekstową
let tekst = msg.payload.message;

if (tekst && tekst.includes("**")) {
    // Wyciągamy to, co jest między gwiazdkami
    let ocenaRaw = tekst.split("**")[1].trim();

    // CAŁKOWICIE nadpisujemy payload, aby nie było tam nic poza oceną
    // Teraz msg.payload będzie zawierał np. "4" albo "5+"
    msg.payload = ocenaRaw; 

    // Opcjonalnie: jeśli chcesz, żeby Node-RED widział to jako liczbę do porównań (np. w Switch)
    // odkomentuj poniższą linię (usuń //), ale wtedy stracisz plusy i minusy (zmienią się w ułamki)
    // msg.payload = parseFloat(ocenaRaw.replace('+', '.5').replace('-', '.75'));

    return msg;
}

// Jeśli nie znaleziono oceny, zatrzymaj przepływ
return null;
